// Fail-fast startup dependency check (FailFastNoSilentFallback).
//
// Every name below is called unguarded by the scripts this shell loads, so
// a missing one is a hard bug: an l8ui bump that drops or renames a file,
// or a script tag that was never added. Without the check the symptom is
// a ReferenceError deep inside a table render, or a feature that silently
// does nothing.
//
// The lists are generated by scanning the loaded scripts for Layer8*/L8*
// globals they call; don't trim one to make a failure go away -- add the
// script tag.
(function() {
    'use strict';

    var REQUIRED_DESKTOP = [
        'L8DIExecute', 'L8DITemplates', 'L8DITransfer', 'L8DataImport', 'L8Health', 'L8Logs',
        'L8NotifyDeliveryLog', 'L8NotifyEnums', 'L8NotifyIntegrationMgmt', 'L8NotifyTargetEditor',
        'L8Security', 'L8SecurityChangePassword', 'L8SecurityPasswordStrength', 'L8Sys',
        'L8SysCredentialsCRUD', 'L8SysDependencyGraph', 'L8SysModules', 'L8SysModulesMap',
        'L8SysRolesCRUD', 'L8SysUsersCRUD', 'Layer8ColumnFactory', 'Layer8CsvExport',
        'Layer8DChart', 'Layer8DChartBar', 'Layer8DChartLine', 'Layer8DChartPie', 'Layer8DConfig',
        'Layer8DDataSource', 'Layer8DDatePicker', 'Layer8DForms', 'Layer8DFormsData',
        'Layer8DFormsFields', 'Layer8DFormsModal', 'Layer8DFormsPickers', 'Layer8DInputFormatter',
        'Layer8DLogo', 'Layer8DModuleCRUD', 'Layer8DModuleFactory', 'Layer8DModuleFilter',
        'Layer8DModuleNavigation', 'Layer8DNotification', 'Layer8DPopup', 'Layer8DReferencePicker',
        'Layer8DReferenceRegistry', 'Layer8DRenderers', 'Layer8DServiceRegistry', 'Layer8DTable',
        'Layer8DThemeSwitcher', 'Layer8DToggleTree', 'Layer8DUtils', 'Layer8DViewFactory',
        'Layer8DWebSocket', 'Layer8DWidget', 'Layer8DatepickerGrid', 'Layer8EnumFactory',
        'Layer8ExcelExport', 'Layer8ExportHelper', 'Layer8FieldParsers', 'Layer8FileUpload',
        'Layer8FormChips', 'Layer8FormFactory', 'Layer8FormatDisplay', 'Layer8InlineTableState',
        'Layer8ModuleConfigFactory', 'Layer8ModuleFactoryCore', 'Layer8PdfExport',
        'Layer8PeriodSelector', 'Layer8QueryBuilder', 'Layer8ReferenceConfigResolver',
        'Layer8SectionConfigs', 'Layer8SectionGenerator', 'Layer8SvgFactory', 'Layer8ViewSwitcher'
    ];

    var REQUIRED_MOBILE = [];

    // Run at DOM-ready, not synchronously: some l8ui modules assign their
    // global after an init() that fires on an already-parsed document
    // (l8ui/popup/layer8d-popup.js). This listener registers before app
    // init's, so it still runs first.
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', check);
    } else {
        check();
    }

    function check() {
        var isMobile = /(^|\/)m\//.test(window.location.pathname);
        var required = isMobile ? REQUIRED_MOBILE : REQUIRED_DESKTOP;
        // A top-level class (Layer8DTable) is a global binding but not a
        // window property, so resolve each name as a global identifier.
        var missing = required.filter(function(name) {
            return new Function('return typeof ' + name)() === 'undefined';
        });
        if (missing.length === 0) return;

        var msg = 'l8tunnel ' + (isMobile ? 'mobile' : 'desktop') + ' shell: ' + missing.length +
            ' required global(s) not loaded: ' + missing.join(', ') + '. A script tag is missing from ' +
            (isMobile ? 'm/app.html' : 'app.html') + ', or the l8ui submodule no longer provides the file that defines it.';
        console.error(msg);
        var banner = document.createElement('div');
        banner.setAttribute('style', 'position:fixed;inset:0;z-index:2147483647;background:#1a0000;color:#ff9b9b;' +
            'padding:24px;font:13px/1.5 monospace;overflow:auto;white-space:pre-wrap');
        banner.textContent = 'Startup dependency check failed\n\n' + msg;
        (document.body || document.documentElement).appendChild(banner);
        throw new Error(msg);
    }
})();
